update_md5_467f43b1db1338b9d01a3c45f27ea.content_md5_467f43b1db1338b9d01a3c45f27e:
it.live("execute releases cache slot when metadata fails before prompt", () =>
  provideTmpdirInstance(() =>
    Effect.gen(function* () {
      const { chat, assistant } = yield* seed()
      const tool = yield* TaskTool
      const def = yield* tool.init()
      const promptOps = stubOps()
      const failed = yield* Effect.exit(
        def.execute(
          {
            description: "inspect bug",
            prompt: "look into the cache key path",
            subagent_type: "general",
          },
          {
            sessionID: chat.id,
            messageID: assistant.id,
            agent: "build",
            abort: new AbortController().signal,
            extra: { promptOps },
            messages: [],
            metadata: () => Effect.fail(new Error("metadata failed")),
            ask: () => Effect.void,
          },
        ),
      )
      const seen: string[] = []

      expect(failed._tag).toBe("Failure")
      yield* executeTask(def, chat, assistant, stubOps({
        onPrompt: (input) => {
          if (input.providerCacheKey) seen.push(input.providerCacheKey)
        },
      }))

      expect(seen).toHaveLength(1)
      expect(seen[0]).toContain(`${chat.id}:general:test:test-model:task-1`)
    }),
  ),
)

